import React from 'react';
import { useFeatureFlag } from '../context/FeatureFlagContext';

const SidebarLayout = ({ children, activeTab, setActiveTab, handleLogout }) => {
    const { isEnabled } = useFeatureFlag();

    // Core navigation items
    let navItems = [
        { id: 'dashboard', label: '📊 Dashboard' },
        { id: 'discover', label: '🔍 Discover' },
        { id: 'chat', label: '💬 Messages' },
        { id: 'matches', label: '❤️ Matches' },
        { id: 'requests', label: '   📬 Incoming Requests' },
        { id: 'sent-interests', label: '   🚀 Sent Interests' },
        { id: 'map', label: '📍 Nearby Map' },
        { id: 'passport', label: '🌍 Passport' }
    ];

    // Settings and Analytics always available as per design
    navItems.push({ id: 'analytics', label: '📈 Analytics' });
    navItems.push({ id: 'settings', label: '⚙️ Settings' });
    navItems.push({ id: 'blocked-users', label: '   🚫 Blocked Users' });
    // navItems initialized above based on flags

    return (
        <div style={{ display: 'flex', width: '100%', height: '100vh', backgroundColor: '#f3f4f6' }}>
            {/* Sidebar */}
            <div style={{ width: '250px', backgroundColor: '#ffffff', borderRight: '1px solid #e5e7eb', padding: '20px', display: 'flex', flexDirection: 'column' }}>
                <h2 style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#e11d48', marginBottom: '30px' }}>Penzi Admin</h2>
                <nav style={{ flex: 1 }}>
                    {navItems.map(item => (
                        <button
                            key={item.id}
                            onClick={() => setActiveTab(item.id)}
                            style={{
                                display: 'block',
                                width: '100%',
                                textAlign: 'left',
                                padding: '12px 16px',
                                marginBottom: '8px',
                                borderRadius: '8px',
                                border: 'none',
                                cursor: 'pointer',
                                backgroundColor: activeTab === item.id ? '#ffe4e6' : 'transparent',
                                color: activeTab === item.id ? '#e11d48' : '#4b5563',
                                fontWeight: activeTab === item.id ? 'bold' : 'normal',
                                transition: 'background-color 0.2s'
                            }}
                        >
                            {item.label}
                        </button>
                    ))}
                </nav>
                <button 
                    onClick={handleLogout}
                    style={{ padding: '12px', border: 'none', backgroundColor: '#fef2f2', color: '#ef4444', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', transition: 'background-color 0.2s' }}
                >
                    Logout
                </button>
            </div>

            {/* Main Content Area */}
            <div style={{ flex: 1, overflowY: 'auto' }}>
                {children}
            </div>
        </div>
    );
};

export default SidebarLayout;
